page_settings.custom_css:
/* SawaTech ASLM 2026 — small visual refinements only. */
selector .st-measure{max-width:780px;margin-inline:auto}
selector .elementor-field-group .elementor-field:focus{border-color:#4F2F6D;box-shadow:0 0 0 3px rgba(79,47,109,.25)}
selector a:focus-visible, selector .elementor-button:focus-visible{outline:3px solid #191919;outline-offset:3px}
selector .st-hero a:focus-visible, selector .st-footer a:focus-visible{outline-color:#fff}
selector .st-step .elementor-button{cursor:default;pointer-events:none}
html{scroll-behavior:smooth}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
